import {t} from './locales.js';import {goatQuote,goatContractReason} from './goat-market-policy.js';import {goatStage} from './goat-state.js';
let expandedContract='';
/** Open a read-only live-livestock quote in the existing shared Market. @param {string} goatId */
export function openGoatContract(goatId){expandedContract=goatId;document.dispatchEvent(new Event('marketopen'));const row=document.querySelector('[data-goat-contract="'+goatId+'"]'),detail=/** @type {HTMLElement|null} */(row?.querySelector('.goat-quote-details')),button=/** @type {HTMLButtonElement|null} */(row?.querySelector('[data-goat-quote]'));if(detail)detail.hidden=false;if(button){button.setAttribute('aria-expanded','true');button.scrollIntoView({block:'nearest'});button.focus({preventScroll:true});}}
/** Presentation only; fulfillment is the following atomic-sale gate. @param {import('./engine.js').State} state @param {HTMLElement} host */
export function renderGoatContracts(state,host){const g=state.goat;if(!g?.visited)return;if(!g.herd.some(h=>h.id===expandedContract))expandedContract='';const section=document.createElement('section');section.id='goat-market';section.setAttribute('aria-labelledby','goat-market-title');const title=document.createElement('h3');title.id='goat-market-title';title.textContent=t('goatLiveContracts');const note=document.createElement('p');note.className='market-note';note.textContent=t('goatContractHelp');section.append(title,note);
 for(const [index,goat]of g.herd.entries()){const quote=goatQuote(state,goat.id),reason=goatContractReason(state,goat.id),stage=goatStage(goat),row=document.createElement('div');row.className='goat-contract';row.dataset.goatContract=goat.id;row.dataset.goatQuotePrice=String(quote.price);row.dataset.goatContractEligible=String(!reason);const line=document.createElement('div');line.className='goat-quote-line';const name=document.createElement('strong');name.textContent=t(stage==='marketReady'?(quote.reason?'goatAdult':'goatReadyAdult'):stage==='growing'?'goatGrowing':'goatWeaned')+' '+(index+1);const price=document.createElement('strong');price.textContent=quote.price?'+'+quote.price+' '+t('coins'):t('goatNoSaleQuote');line.append(name,price);const b=document.createElement('button');b.type='button';b.className='action-button';b.dataset.goatQuote=goat.id;b.textContent=t('goatViewQuote');const detail=document.createElement('div');detail.id='goat-quote-'+goat.id;detail.className='goat-quote-details';detail.hidden=expandedContract!==goat.id;b.setAttribute('aria-expanded',String(!detail.hidden));b.setAttribute('aria-controls',detail.id);b.addEventListener('click',()=>{const opening=detail.hidden;expandedContract=opening?goat.id:'';detail.hidden=!opening;b.setAttribute('aria-expanded',String(opening));});const summary=document.createElement('p');summary.textContent=t('goatLiveAnimal')+' · '+Math.round(goat.condition*100)+'% '+t('goatBodyCondition')+' · '+Math.floor(goat.growth*100)+'% '+t('goatGrowth');const group=document.createElement('p');group.textContent=t('goatHerdAfter')+': '+quote.herdAfter+' · '+t('goatSocialInfo');detail.append(summary,group);if(reason){const why=document.createElement('p');why.className='market-note';why.textContent=t(reason);detail.append(why);}else{const ready=document.createElement('p');ready.className='market-note';ready.textContent=t('goatQuoteReady');detail.append(ready);}row.append(line,b,detail);section.append(row);}
 host.append(section);
}
